import{ACCOUNT_TYPES,IN_CATEGORIES,OUT_CATEGORIES,REPORTS,accountBalance,archiveAccount,changeChequeStatus,closeCash,completeReconciliation,confirmImport,createTransfer,dashboardMetrics,initialState,money,previewImport,recordTransaction,reportRows,reopenReconciliation,reverseTransaction,rollbackImport,saveAccount,saveCheque,saveRule,startReconciliation,today,toCsv}from"./core.js";import{createRepository}from"./repository.js";import{commitAllocations,loadDocuments}from"./connectors.js";import{workbookDatasets}from"./xlsx.js";
import{createWorkspaceStateStorage}from"/supabase/workspace.js";const localStorage=await createWorkspaceStateStorage();
const repo=createRepository(),$=s=>document.querySelector(s),esc=v=>String(v??"").replace(/[&<>"']/g,x=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[x])),icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="${{home:"M3 11l9-8 9 8v9H3z",bank:"M3 10h18M5 10v8m4-8v8m6-8v8m4-8v8M2 21h20M4 7l8-4 8 4",rows:"M4 5h16M4 12h16M4 19h16",upload:"M12 16V4m0 0L7 9m5-5 5 5M4 20h16",check:"M5 12l4 4L19 6",plus:"M12 5v14M5 12h14",cash:"M3 6h18v12H3zM8 12h8",rules:"M4 6h16M7 12h10M10 18h4",report:"M5 3h14v18H5zM8 15l3-3 2 2 3-4",settings:"M12 8a4 4 0 100 8 4 4 0 000-8zM12 2v3m0 14v3M2 12h3m14 0h3",menu:"M4 6h16M4 12h16M4 18h16",search:"M11 4a7 7 0 100 14 7 7 0 000-14zm5 12l5 5"}[n]||"M4 12h16"}"/></svg>`;
let state=repo.load(),view="Dashboard",pending=null;const nav=["Dashboard","Accounts","Bank Transactions","Statement Import","Reconciliation","Money In","Money Out","Transfers","Cash Management","Cheques","Cards / UPI / Wallets","Bank Rules","Reports","Import / Export","Settings & Privacy"];
function save(s){state=repo.save(s)}function toast(m,e=false){$("#bank-toast").innerHTML=`<div class="toast ${e?"error":""}">${esc(m)}</div>`;setTimeout(()=>$("#bank-toast").innerHTML="",2800)}function options(a,val=""){return a.map(x=>`<option ${x===val?"selected":""}>${esc(x)}</option>`).join("")}function accounts(val="",filter=()=>true){return state.accounts.filter(x=>x.active&&filter(x)).map(x=>`<option value="${x.id}" ${x.id===val?"selected":""}>${esc(x.name)}</option>`).join("")}function badge(x){const c=/paid|matched|cleared|completed|valid|active/i.test(x)?"success":/error|bounced|reversed|rejected/i.test(x)?"danger":"warn";return`<span class="badge ${c}">${esc(x)}</span>`}function dl(n,t,type="text/csv"){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([t],{type}));a.download=n;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function shell(body){return`<div class="app-shell"><aside class="sidebar"><a class="sidebar-brand" href="/index.html"><img src="/infobridgeindia-logo.png"></a><div class="workspace-label"><strong>Banking</strong><span>Cash & reconciliation</span></div><nav>${nav.map((n,i)=>`<button class="nav-link ${n===view?"active":""}" data-view="${esc(n)}">${icon(["home","bank","rows","upload","check","plus","plus","rows","cash","rows","bank","rules","report","upload","settings"][i])}<span>${esc(n)}</span></button>`).join("")}</nav><div class="local-note">Local-first workspace<span> No bank credentials stored</span><a href="/index.html">Exit to website</a></div></aside><main class="main"><header class="topbar"><button class="icon-button mobile-menu" data-menu>${icon("menu")}</button><label class="global-search">${icon("search")}<input id="search" placeholder="Search banking records"></label><div class="top-actions"><button class="btn secondary compact" data-action="backup">Export backup</button></div></header><div class="content">${body}</div><nav class="mobile-nav">${["Dashboard","Accounts","Bank Transactions","Reports"].map(n=>`<button data-view="${n}" class="${n===view?"active":""}">${icon(n==="Dashboard"?"home":n==="Reports"?"report":"bank")}<span>${n}</span></button>`).join("")}</nav></main></div>`}
const head=(title,desc,actions="")=>`<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="page-actions">${actions}</div></div>`,empty=(title,text,action="")=>`<div class="empty"><div class="empty-icon">${icon("bank")}</div><h3>${title}</h3><p>${text}</p>${action}</div>`,table=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join("")}</tr></thead><tbody>${rows.join("")}</tbody></table></div>`;
function dashboard(){const m=dashboardMetrics(state);return head("Banking overview","Balances, cash movement and reconciliation status.",`<button class="btn secondary" data-view="Statement Import">Import statement</button><button class="btn primary" data-action="money-in">${icon("plus")} Money In</button>`)+`<section class="metrics">${[["Bank balance",m.bankBalance],["Cash balance",m.cashBalance],["Money in today",m.inToday],["Money out today",m.outToday],["Receipts this month",m.monthReceipts],["Payments this month",m.monthPayments],["Unreconciled",m.unreconciled],["Pending cheques",m.pendingCheques]].map(([a,b])=>`<article class="metric"><span>${a}</span><strong>${typeof b==="number"&&a!=="Unreconciled"&&a!=="Pending cheques"?money(b):b}</strong></article>`).join("")}</section><section class="quick-card"><div><h2>Daily banking actions</h2><p>Record, import, match and reconcile from one connected workspace.</p></div><div class="quick-actions"><button class="action-chip" data-action="money-in">Money In</button><button class="action-chip" data-action="money-out">Money Out</button><button class="action-chip" data-action="transfer">Transfer</button><button class="action-chip" data-view="Reconciliation">Reconcile</button></div></section><section class="panel"><div class="panel-head"><h2>Recent bank transactions</h2><button class="text-button" data-view="Bank Transactions">View all</button></div>${transactionTable(state.transactions.slice(0,8))}</section>`}
function transactionTable(rows){return rows.length?table(["Date","Account","Description","Reference","Money in","Money out","Status","Action"],rows.map(x=>`<tr><td>${x.date}</td><td>${esc(state.accounts.find(a=>a.id===x.accountId)?.name||"—")}</td><td>${esc(x.description)}</td><td class="mono">${esc(x.reference||"—")}</td><td class="num in">${x.moneyIn?money(x.moneyIn):"—"}</td><td class="num out">${x.moneyOut?money(x.moneyOut):"—"}</td><td>${badge(x.status)}</td><td><button class="text-button" data-match="${x.id}">Match</button>${x.status!=="Reversed"?` <button class="more" data-reverse="${x.id}">Reverse</button>`:""}</td></tr>`)):empty("No transactions yet","Record money in/out or import a bank statement.")}
function accountView(cards=false){const rows=state.accounts.filter(a=>cards?["Credit Card","UPI Account","Digital Wallet","Payment Gateway Clearing Account"].includes(a.type):true);return head(cards?"Cards, UPI & wallets":"Accounts",cards?"Track non-bank payment instruments and clearing accounts.":"Bank, cash, overdraft and clearing accounts.",`<button class="btn primary" data-action="account">${icon("plus")} Add account</button>`)+`<div class="banking-grid">${rows.map(a=>`<article class="warehouse-card"><span class="warehouse-code">${esc(a.type)}</span><h2>${esc(a.name)}</h2><p>${esc(a.bankName||a.upiId||a.walletProvider||"Local account")}</p><div class="balance">${money(accountBalance(state,a.id))}</div><p>${a.accountNumber?`Account ending ${esc(String(a.accountNumber).slice(-4))}`:"No sensitive credentials stored"}</p><button class="btn secondary compact" data-archive="${a.id}">Archive</button></article>`).join("")||empty("No accounts","Add the first account to begin.")}</div>`}
function txView(direction){const title=direction?`Money ${direction}`:"Bank Transactions";return head(title,direction?`Record a controlled Money ${direction.toLowerCase()} entry.`:"Review imported and manual transactions.",`<button class="btn ${direction?"primary":"secondary"}" data-action="money-${(direction||"in").toLowerCase()}">${icon("plus")} ${direction?`Money ${direction}`:"Add transaction"}</button>`)+`<section class="panel"><div class="panel-head"><h2>${title}</h2><span>${state.transactions.filter(x=>!direction||x.direction===direction).length} records</span></div>${transactionTable(state.transactions.filter(x=>!direction||x.direction===direction))}</section>`}
function transfers(){return head("Transfers","Linked account-to-account movements with traceable charges.",`<button class="btn primary" data-action="transfer">New transfer</button>`)+`<section class="panel">${state.transfers.length?table(["Number","Date","From","To","Amount","Charges","Status"],state.transfers.map(x=>`<tr><td class="mono">${x.id}</td><td>${x.date}</td><td>${esc(state.accounts.find(a=>a.id===x.fromAccountId)?.name)}</td><td>${esc(state.accounts.find(a=>a.id===x.toAccountId)?.name)}</td><td>${money(x.amount)}</td><td>${money(x.charges)}</td><td>${badge(x.status)}</td></tr>`)):empty("No transfers","Transfer funds between active accounts without duplicating balances.")}</section>`}
function imports(){return head("Statement Import","Parse local CSV/XLSX statements, map columns and prevent duplicates.")+`<section class="panel padded"><div class="upload-drop"><h2>Import bank statement</h2><p>Files remain in your browser. CSV and modern XLSX are supported.</p><label>Target account<select class="input" id="import-account"><option value="">Select account</option>${accounts()}</select></label><label class="btn primary file-button">Choose statement<input id="statement-file" type="file" accept=".csv,.xlsx"></label></div></section><section class="panel export-panel"><div class="panel-head"><h2>Import history</h2></div>${state.importBatches.length?table(["File","Imported","Duplicates","Rejected","Status","Action"],state.importBatches.map(x=>`<tr><td>${esc(x.fileName)}</td><td>${x.importedRows}</td><td>${x.duplicateRows}</td><td>${x.rejectedRows}</td><td>${badge(x.status)}</td><td><button class="text-button" data-rollback="${x.id}">Rollback</button></td></tr>`)):empty("No statement imports","Select an account and upload a CSV or XLSX statement.")}</section>`}
function reconciliation(){return head("Reconciliation","Compare book movement with a statement closing balance.",`<button class="btn primary" data-action="reconcile">Start reconciliation</button>`)+`<section class="panel">${state.reconciliations.length?table(["Number","Period","Book closing","Statement closing","Difference","Status","Action"],state.reconciliations.map(x=>`<tr><td class="mono">${x.id}</td><td>${x.startDate} – ${x.endDate}</td><td>${money(x.bookClosing)}</td><td>${money(x.closingStatementBalance)}</td><td>${money(x.difference)}</td><td>${badge(x.status)}</td><td>${x.status==="Open"?`<button class="text-button" data-complete="${x.id}">Complete</button>`:`<button class="text-button" data-reopen="${x.id}">Reopen</button>`}</td></tr>`)):empty("No reconciliations","Start with a statement period and closing balance.")}</section>`}
function cash(){return head("Cash Management","Daily cash balances, closings and controlled variances.",`<button class="btn primary" data-action="cash-close">Close cash day</button>`)+`<section class="panel">${state.cashClosings.length?table(["Date","Account","Expected","Physical","Variance","Closed by"],state.cashClosings.map(x=>`<tr><td>${x.date}</td><td>${esc(state.accounts.find(a=>a.id===x.accountId)?.name)}</td><td>${money(x.expectedClosing)}</td><td>${money(x.physicalCash)}</td><td>${money(x.difference)}</td><td>${esc(x.closedBy)}</td></tr>`)):empty("No cash closings","Complete a cash closing to preserve the daily audit trail.")}</section>`}
function cheques(){return head("Cheques","Track received and issued cheques through clearance.",`<button class="btn primary" data-action="cheque">Add cheque</button>`)+`<section class="panel">${state.cheques.length?table(["Cheque","Date","Direction","Amount","Status","Action"],state.cheques.map(x=>`<tr><td class="mono">${esc(x.chequeNumber)}</td><td>${x.date}</td><td>${x.direction}</td><td>${money(x.amount)}</td><td>${badge(x.status)}</td><td>${["Received/Issued","Deposited/Presented","Pending Clearance"].includes(x.status)?`<button class="text-button" data-cheque="${x.id}">Update</button>`:"—"}</td></tr>`)):empty("No cheques","Add a received or issued cheque.")}</section>`}
function rules(){return head("Bank Rules","Preview-first categorisation rules for imported narrations.",`<button class="btn primary" data-action="rule">New rule</button>`)+`<section class="panel">${state.rules.length?table(["Rule","Condition","Action","Priority","Status"],state.rules.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.field)} ${esc(x.operator)} “${esc(x.value)}”</td><td>${esc(x.actionType)} → ${esc(x.actionValue)}</td><td>${x.priority}</td><td>${badge(x.active?"Active":"Inactive")}</td></tr>`)):empty("No bank rules","Create a rule for repeatable statement classification.")}</section>`}
function reports(){const type=sessionStorage.getItem("bank-report")||REPORTS[0],rows=reportRows(state,type);return head("Banking Reports","Operational registers derived from saved banking records.",`<button class="btn secondary" data-report-export="${esc(type)}">Export CSV</button>`)+`<div class="report-tabs">${REPORTS.map(x=>`<button class="${x===type?"active":""}" data-report="${esc(x)}">${esc(x)}</button>`).join("")}</div><section class="panel"><div class="panel-head"><h2>${esc(type)}</h2><span>${rows.length} rows</span></div>${rows.length?table(Object.keys(rows[0]).filter(k=>typeof rows[0][k]!=="object").slice(0,8),rows.map(r=>`<tr>${Object.keys(rows[0]).filter(k=>typeof rows[0][k]!=="object").slice(0,8).map(k=>`<td>${esc(r[k])}</td>`).join("")}</tr>`)):empty("No report data","Records will appear here as banking activity is captured.")}</section>`}
function dataView(){return head("Import / Export","Portable backups for this Banking workspace only.")+`<section class="two-col"><article class="panel padded"><h2>Export backup</h2><p>Download accounts, transactions, mappings and audit history.</p><button class="btn primary" data-action="backup">Export JSON</button></article><article class="panel padded"><h2>Restore backup</h2><p>Validate and replace this Banking workspace from a compatible backup.</p><label class="btn secondary file-button">Choose backup<input id="restore-file" type="file" accept=".json"></label></article></section>`}
function settings(){return head("Settings & Privacy","Workspace controls and local-data safeguards.")+`<section class="panel padded"><div class="form-grid"><label>Financial year<input class="input" id="fy" value="${esc(state.settings.financialYear)}"></label><label>Date format<select class="input" id="df">${options(["DD/MM/YYYY","MM/DD/YYYY","YYYY-MM-DD"],state.settings.dateFormat)}</select></label><label>Reconciliation period<select class="input" id="rp">${options(["Monthly","Weekly","Quarterly"],state.settings.reconciliationPeriod)}</select></label><label>Match tolerance days<input class="input" id="tol" type="number" value="${state.settings.matchToleranceDays}"></label></div><p class="form-note">Bank passwords, PINs, OTPs and CVVs are never requested or stored. Banking data remains local to this browser unless you export it.</p><button class="btn primary" data-action="settings-save">Save settings</button></section>`}
function render(){let body=view==="Dashboard"?dashboard():view==="Accounts"?accountView():view==="Bank Transactions"?txView():view==="Statement Import"?imports():view==="Reconciliation"?reconciliation():view==="Money In"?txView("In"):view==="Money Out"?txView("Out"):view==="Transfers"?transfers():view==="Cash Management"?cash():view==="Cheques"?cheques():view==="Cards / UPI / Wallets"?accountView(true):view==="Bank Rules"?rules():view==="Reports"?reports():view==="Import / Export"?dataView():settings();$("#bank-app").className="";$("#bank-app").innerHTML=shell(body);wire()}
function modal(title,body,fn,label="Save"){$("#bank-modal").innerHTML=`<div class="modal-backdrop"><section class="modal wide"><form><header><h2>${title}</h2><button type="button" class="icon-button" data-close>×</button></header><div class="modal-body">${body}</div><footer><button type="button" class="btn secondary" data-close>Cancel</button><button class="btn primary">${label}</button></footer></form></section></div>`;document.querySelectorAll("[data-close]").forEach(x=>x.onclick=()=>$("#bank-modal").innerHTML="");$("#bank-modal form").onsubmit=e=>{e.preventDefault();try{fn(Object.fromEntries(new FormData(e.target)));$("#bank-modal").innerHTML="";render();toast("Saved") }catch(x){toast(x.message,true)}}}
const field=(n,l,type="text",v="",extra="")=>`<label>${l}<input class="input" name="${n}" type="${type}" value="${esc(v)}" ${extra}></label>`;
function act(a){if(a==="account")modal("Add account",`<div class="form-grid">${field("name","Account name") }<label>Type<select class="input" name="type">${options(ACCOUNT_TYPES)}</select></label>${field("bankName","Bank / provider")}${field("accountNumber","Account number (display only)")}${field("currency","Currency","text","INR")}${field("openingBalanceDate","Opening balance date","date",today())}${field("openingBalance","Opening balance","number","0","step=.01")}</div>`,v=>save(saveAccount(state,v).state));else if(a.startsWith("money-")){const d=a.endsWith("in")?"In":"Out";modal(`Money ${d}`,`<div class="form-grid"><label>Account<select class="input" name="accountId">${accounts()}</select></label>${field("date","Date","date",today())}<label>Category<select class="input" name="category">${options(d==="In"?IN_CATEGORIES:OUT_CATEGORIES)}</select></label>${field("amount","Amount","number","","step=.01")}${field("description","Description")}${field("reference","Reference")}</div>`,v=>save(recordTransaction(state,{...v,direction:d}).state),`Record Money ${d}`)}else if(a==="transfer")modal("New transfer",`<div class="form-grid"><label>From<select class="input" name="fromAccountId">${accounts()}</select></label><label>To<select class="input" name="toAccountId">${accounts()}</select></label>${field("date","Date","date",today())}${field("amount","Amount","number","","step=.01")}${field("charges","Bank charges","number","0","step=.01")}${field("reference","Reference")}</div>`,v=>save(createTransfer(state,v).state));else if(a==="reconcile")modal("Start reconciliation",`<div class="form-grid"><label>Account<select class="input" name="accountId">${accounts()}</select></label>${field("reconciliationDate","Reconciliation date","date",today())}${field("startDate","Period start","date",today().slice(0,8)+"01")}${field("endDate","Period end","date",today())}${field("openingStatementBalance","Opening statement balance","number","0","step=.01")}${field("closingStatementBalance","Closing statement balance","number","0","step=.01")}</div>`,v=>save(startReconciliation(state,v).state));else if(a==="cash-close")modal("Close cash day",`<div class="form-grid"><label>Cash account<select class="input" name="accountId">${accounts("",a=>["Cash Account","Petty Cash"].includes(a.type))}</select></label>${field("date","Date","date",today())}${field("physicalCash","Physical cash","number","0","step=.01")}${field("closedBy","Closed by","text","Current account")}${field("reason","Variance reason")}</div>`,v=>save(closeCash(state,v).state));else if(a==="cheque")modal("Add cheque",`<div class="form-grid">${field("chequeNumber","Cheque number")}${field("date","Date","date",today())}<label>Account<select class="input" name="accountId">${accounts()}</select></label><label>Direction<select class="input" name="direction">${options(["In","Out"])}</select></label>${field("amount","Amount","number","","step=.01")}${field("partyName","Party name")}</div>`,v=>save(saveCheque(state,v).state));else if(a==="rule")modal("New bank rule",`<div class="form-grid">${field("name","Rule name")}<label>Field<select class="input" name="field">${options(["description","reference","amount"])}</select></label><label>Operator<select class="input" name="operator">${options(["contains","starts with","ends with","equals","greater","less","between"])}</select></label>${field("value","Match value")}<label>Action<select class="input" name="actionType">${options(["category","note","customer","supplier"])}</select></label>${field("actionValue","Action value")}${field("priority","Priority","number","100")}</div>`,v=>save(saveRule(state,v).state));else if(a==="backup")dl("infobridgeindia-banking-backup.json",repo.export(state),"application/json");else if(a==="settings-save"){state.settings={...state.settings,financialYear:$("#fy").value,dateFormat:$("#df").value,reconciliationPeriod:$("#rp").value,matchToleranceDays:+$("#tol").value};save(state);toast("Settings saved")}}
function match(id){const tx=state.transactions.find(x=>x.id===id),d=loadDocuments(),docs=tx.direction==="In"?d.invoices:d.bills,module=tx.direction==="In"?"Sales":"Purchases";modal("Match transaction",docs.length?`<p>Allocate up to ${money(tx.amount)}. Existing module balances are updated without duplicate documents.</p>${docs.map(x=>`<label>${esc(x.invoiceNumber||x.billNumber||x.id)} · due ${money(x.balanceDue)}<input class="input" type="number" step=".01" name="${x.id}" value="0"></label>`).join("")}`:empty("No outstanding documents",`No ${module.toLowerCase()} documents currently have an outstanding balance.`),v=>{const items=Object.entries(v).filter(([,a])=>+a>0).map(([documentId,amount])=>({module,documentId,amount:+amount}));save(commitAllocations(state,id,items).state)},"Apply allocation")}
async function statement(file){try{const accountId=$("#import-account").value;if(!accountId)throw Error("Select a target account first");const sets=await workbookDatasets(file);if(!sets.length)throw Error("No transaction rows found");const ds=sets[0],h=Object.keys(ds.rows[0]),guess=(terms)=>h.find(x=>terms.some(t=>x.toLowerCase().includes(t)))||"";pending={accountId,fileName:file.name,rows:ds.rows,mapping:{date:guess(["date"]),valueDate:guess(["value date"]),description:guess(["narration","description","particular"]),reference:guess(["reference","ref","utr"]),debit:guess(["debit","withdrawal"]),credit:guess(["credit","deposit"]),amount:guess(["amount"]),type:guess(["type","dr/cr"]),balance:guess(["balance"]),utr:guess(["utr"]),cheque:guess(["cheque"])} };mappingModal(h,sets)}catch(x){toast(x.message,true)}}function mappingModal(headers,sets){const select=(n)=>`<label>${n}<select class="input" name="${n}"><option value="">Not mapped</option>${headers.map(h=>`<option ${pending.mapping[n]===h?"selected":""}>${esc(h)}</option>`).join("")}</select></label>`;modal("Map statement columns",`<p>Detected ${sets.length} worksheet(s): ${sets.map(x=>`${esc(x.sheetName)} (${x.rows.length})`).join(", ")}. Mapping the first populated sheet.</p><div class="mapping-grid">${["date","valueDate","description","reference","debit","credit","amount","type","balance","utr","cheque"].map(select).join("")}</div><label>Date format<select class="input" name="dateFormat">${options(["DD/MM/YYYY","MM/DD/YYYY","YYYY-MM-DD"],state.settings.importDateFormat)}</select></label>${field("profileName","Save mapping profile", "text",pending.fileName)}`,v=>{const mapping={...v};delete mapping.dateFormat;delete mapping.profileName;const p=previewImport(state,{...pending,mapping,dateFormat:v.dateFormat});const ok=p.filter(x=>x.status==="Valid").length,dup=p.filter(x=>x.duplicate).length,bad=p.filter(x=>x.errors.length).length;if(!confirm(`Import ${ok} valid rows? ${dup} duplicates and ${bad} rejected rows will be skipped.`))return;save(confirmImport(state,p,{...pending,mapping,dateFormat:v.dateFormat,profileName:v.profileName}).state)},"Preview & import")}
function wire(){document.querySelectorAll("[data-view]").forEach(x=>x.onclick=()=>{view=x.dataset.view;render()});$("[data-menu]")?.addEventListener("click",()=>$(".sidebar").classList.toggle("open"));document.querySelectorAll("[data-action]").forEach(x=>x.onclick=()=>act(x.dataset.action));document.querySelectorAll("[data-archive]").forEach(x=>x.onclick=()=>{if(confirm("Archive this account? Existing records remain available.")){save(archiveAccount(state,x.dataset.archive));render()}});document.querySelectorAll("[data-reverse]").forEach(x=>x.onclick=()=>{const r=prompt("Reversal reason");if(r)try{save(reverseTransaction(state,x.dataset.reverse,r));render()}catch(e){toast(e.message,true)}});document.querySelectorAll("[data-match]").forEach(x=>x.onclick=()=>match(x.dataset.match));document.querySelectorAll("[data-rollback]").forEach(x=>x.onclick=()=>{try{save(rollbackImport(state,x.dataset.rollback));render()}catch(e){toast(e.message,true)}});document.querySelectorAll("[data-complete]").forEach(x=>x.onclick=()=>{try{save(completeReconciliation(state,x.dataset.complete,prompt("Adjustment reason (only required for a non-zero difference)")||""));render()}catch(e){toast(e.message,true)}});document.querySelectorAll("[data-reopen]").forEach(x=>x.onclick=()=>{const r=prompt("Reason for reopening");if(r){save(reopenReconciliation(state,x.dataset.reopen,r));render()}});document.querySelectorAll("[data-cheque]").forEach(x=>x.onclick=()=>{const status=prompt("Next status: Deposited/Presented, Pending Clearance, Cleared, Bounced or Cancelled");if(status)try{save(changeChequeStatus(state,x.dataset.cheque,status,{reason:/Bounced|Cancelled/.test(status)?prompt("Reason")||"":""}));render()}catch(e){toast(e.message,true)}});document.querySelectorAll("[data-report]").forEach(x=>x.onclick=()=>{sessionStorage.setItem("bank-report",x.dataset.report);render()});document.querySelectorAll("[data-report-export]").forEach(x=>x.onclick=()=>dl(`${x.dataset.report}.csv`,toCsv(reportRows(state,x.dataset.report))));$("#statement-file")?.addEventListener("change",e=>statement(e.target.files[0]));$("#restore-file")?.addEventListener("change",async e=>{try{if(confirm("Replace the current Banking workspace with this backup?")){save(repo.restore(await e.target.files[0].text()));render();toast("Backup restored")}}catch(x){toast(x.message,true)}});$("#search")?.addEventListener("input",e=>{const q=e.target.value.toLowerCase();document.querySelectorAll("tbody tr").forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q))})}
